  "result": "PASS: layout e assets locais",
  "width": 360,
  "images": 13
}
### Ran Playwright code
```js
await page.evaluate('async () => {await document.fonts.ready;if(document.documentElement.scrollWidth>innerWidth)throw Error("Overflow");const imgs=[...document.images].filter(i=>i.getAttribute("src").startsWith("/figma/"));await Promise.all(imgs.map(i=>i.decode()));if(imgs.some(i=>!i.naturalWidth))throw Error("Asset ausente");return {result:"PASS: layout e assets locais",width:innerWidth,images:imgs.length};}');
```

